// Admin Page
// View all users and look up any user's transactions by their userId

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './AdminPage.css';

const ADMIN_KEY = 'fms-admin-2026';
const BASE = 'http://localhost:5000/api/admin';
const headers = { 'x-admin-key': ADMIN_KEY };

function AdminPage() {
  const [users, setUsers]               = useState([]);
  const [loadingUsers, setLoadingUsers] = useState(true);
  const [usersError, setUsersError]     = useState('');

  const [searchId, setSearchId]         = useState('');
  const [result, setResult]             = useState(null);
  const [searching, setSearching]       = useState(false);
  const [searchError, setSearchError]   = useState('');

  // Load all users on mount
  useEffect(() => {
    axios.get(`${BASE}/users`, { headers })
      .then(res => setUsers(res.data.users))
      .catch(() => setUsersError('Could not load users. Is the backend running?'))
      .finally(() => setLoadingUsers(false));
  }, []);

  // Look up transactions for a specific userId
  const handleSearch = async (e) => {
    e.preventDefault();
    if (!searchId.trim()) return;

    setSearching(true);
    setSearchError('');
    setResult(null);

    try {
      const res = await axios.get(`${BASE}/users/${searchId}/transactions`, { headers });
      setResult(res.data);
    } catch (err) {
      const msg = err.response?.data?.message || 'User not found';
      setSearchError(msg);
    } finally {
      setSearching(false);
    }
  };

  // Click a user row to auto-fill the search
  const handleUserClick = (id) => {
    setSearchId(String(id));
    setResult(null);
    setSearchError('');
  };

  return (
    <div className="admin-page">
      <div className="admin-container">

        {/* ── Header ── */}
        <div className="admin-header">
          <h1>🛠️ Admin Panel</h1>
          <p>View all users and look up transactions by User ID</p>
        </div>

        <div className="admin-layout">

          {/* ── Left: Users Table ── */}
          <div className="admin-left">
            <div className="admin-card">
              <h2>All Users</h2>

              {loadingUsers && <p className="admin-loading">Loading users...</p>}
              {usersError   && <p className="admin-error">{usersError}</p>}

              {!loadingUsers && !usersError && (
                <table className="admin-table">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Name</th>
                      <th>Email</th>
                      <th>Joined</th>
                    </tr>
                  </thead>
                  <tbody>
                    {users.map(u => (
                      <tr
                        key={u.id}
                        className={`admin-row ${String(u.id) === searchId ? 'active-row' : ''}`}
                        onClick={() => handleUserClick(u.id)}
                        title="Click to view transactions"
                      >
                        <td><span className="user-id-badge">#{u.id}</span></td>
                        <td>{u.name}</td>
                        <td>{u.email}</td>
                        <td>{new Date(u.createdAt).toLocaleDateString()}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>

          {/* ── Right: Search + Results ── */}
          <div className="admin-right">

            {/* Search box */}
            <div className="admin-card">
              <h2>Search by User ID</h2>
              <form onSubmit={handleSearch} className="search-form">
                <input
                  type="number"
                  min="1"
                  placeholder="Enter User ID (e.g. 3)"
                  value={searchId}
                  onChange={e => setSearchId(e.target.value)}
                  className="search-input"
                />
                <button type="submit" className="search-btn" disabled={searching}>
                  {searching ? 'Searching...' : '🔍 View Transactions'}
                </button>
              </form>
              <p className="search-hint">
                💡 Or click any user in the table on the left
              </p>
            </div>

            {/* Error */}
            {searchError && (
              <div className="admin-card error-card">
                <p className="admin-error">❌ {searchError}</p>
              </div>
            )}

            {/* Results */}
            {result && (
              <>
                {/* User info + summary */}
                <div className="admin-card">
                  <h2>
                    👤 {result.user.name}
                    <span className="user-id-badge" style={{ marginLeft: 8 }}>
                      ID #{result.user.id}
                    </span>
                  </h2>
                  <p className="user-email">{result.user.email}</p>

                  <div className="summary-strip">
                    <div className="summary-pill">
                      <span className="pill-label">Transactions</span>
                      <span className="pill-value">{result.summary.totalTransactions}</span>
                    </div>
                    <div className="summary-pill income-pill">
                      <span className="pill-label">Income</span>
                      <span className="pill-value">₹{result.summary.totalIncome}</span>
                    </div>
                    <div className="summary-pill expense-pill">
                      <span className="pill-label">Expense</span>
                      <span className="pill-value">₹{result.summary.totalExpense}</span>
                    </div>
                    <div className="summary-pill balance-pill">
                      <span className="pill-label">Balance</span>
                      <span className="pill-value">₹{result.summary.balance}</span>
                    </div>
                  </div>
                </div>

                {/* Transactions table */}
                <div className="admin-card">
                  <h2>Transactions ({result.transactions.length})</h2>

                  {result.transactions.length === 0 ? (
                    <p className="admin-empty">No transactions found for this user.</p>
                  ) : (
                    <div className="table-scroll">
                      <table className="admin-table">
                        <thead>
                          <tr>
                            <th>ID</th>
                            <th>Title</th>
                            <th>Category</th>
                            <th>Date</th>
                            <th>Type</th>
                            <th>Amount</th>
                          </tr>
                        </thead>
                        <tbody>
                          {result.transactions.map(t => (
                            <tr key={t.id}>
                              <td>{t.id}</td>
                              <td>{t.title}</td>
                              <td>{t.category}</td>
                              <td>{t.date}</td>
                              <td>
                                <span className={`type-badge ${t.type}`}>
                                  {t.type}
                                </span>
                              </td>
                              <td className={`amount ${t.type}`}>
                                {t.type === 'income' ? '+' : '-'}₹{parseFloat(t.amount).toFixed(2)}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default AdminPage;
